from thefuck import shells


def match(command, settings):
    script_text = command.script
    error_text = command.stderr.lower()
    return script_text.startswith('vagrant ') and 'run `vagrant up`' in error_text


def get_new_command(command, settings):
    parts = command.script.split(' ')
    target = ""
    if len(parts) >= 3:
        target = parts[2]
    return shells.and_("vagrant up " + target, command.script)
